"Видео: Что делает устройство?": "Видео: Ускунә немә қилиду?",
"Угадай устройство": "Қандақ ускуне екәнлигини тапиң",
"Я опишу устройство, а ты угадаешь, что это. Читай внимательно.": "Мән ускунини тәрипләймән, сән қандақ ускунә екәнлигини таписән. Диққәт билән оқуң.",
"Управляем или смотрим?": "Башқурамду яки көрәмду?",
"Одними устройствами мы управляем: это клавиатура, мышь и джойстик. Другие показывают, печатают или звучат: монитор, принтер, колонки и наушники. Реши, к какой группе относится устройство.": "Бәзи ускуниләр билән башқуримиз: клавиатура, чичқанчә вә джойстик. Башқилири көрситиду, бесип чиқириду яки авазланду: монитор, принтер, динамик вә қулақлиқ. Ускунә қайси гуруппиға мәнсуп екәнлигини бәлгүләң.",
"Проверим себя": "Өзүмизни тәкшүрүп көрәйли",
"Повторим всё вместе: названия, описания и группы устройств.": "Һәммини биллә тәкрарлайли: ускуниләрниң намлири, тәрипи вә гурупилири.",
"Видео: Правила работы": "Видео: Ишләш қаидилири",
"Правила за компьютером": "Компьютер алдидики қаидиләр",
"За компьютером нужно вести себя правильно. Сиди прямо и не слишком близко к экрану. Делай перерывы, когда устали глаза. Не трогай розетки и провода. Никому не говори свой пароль. А если что-то напугало, позови взрослого. Нажимай на карточки и читай.": "Компьютер алдида өзүңни тоғра тутуш керәк. Тик олтир, экранға жиқин олтарма. Көз чарчиса, дәм ел. Розетка вә симларға тутушма. Сирлиқ нөмириңни һеч кимгә ейтма. Әгәр бирәр нәрсә қорқутса, чоң кишини чақир. Карточкиларни бесип оқуң.",
"Правильно или нет?": "Тоғрими яки әмәсму?",
"Прочитай правило и скажи, правильно ли так делать.": "Қаидини оқуп, шундақ қилиш тоғрами-әмәсликини ейтиң.",
"Проверим правила": "Қаидиләрни тәкшүрәйли",
"Ещё раз проверим правила и устройства.": "Қаидә вә ускунилирини йәнә бир тәкшүрәйли.",
"Видео: Порядок действий": "Видео: Һәрикәт тәртипи",
"Расставь шаги по порядку": "Қәдәмләрни тәртипкә қоюң",
"Компьютер умеет выполнять действия только по порядку, шаг за шагом. Такой порядок действий называют алгоритмом. Попробуй сам. Нажимай на шаги по порядку: что делаем сначала, что потом.": "Компьютер һәрикәтләрни пәқәт тәртип билән, бир қәдәм-бир қәдәмдин орунлайду. Мундақ һәрикәт тәртипини алгоритм дәймиз. Өзүң синап көр. Қәдәмләрни тәртип билән бесиң: авал немә қилимиз, андин немә.",
"Что делаем раньше?": "Қайсисини авал қилимиз?",
"Ответь, что нужно сделать первым, последним, а что сразу после этого шага.": "Жавап бериң: немини биринчи, немини ахирида қилиш керәк вә бу қәдәмдин кейин дәрһал немә келиду.",
"Смешанные задания": "Арилаш тапшурмилар",
"Последняя проверка курса. Устройства, правила и порядок действий.": "Курсниң ахирқи тәкшүрүши. Ускунилар, қаидиләр вә һәрикәт тәртипи.",
"Курс пройден!": "Курс тамамланди!",
"Теперь ты знаешь устройства компьютера, правила безопасной работы и умеешь расставлять шаги по порядку. Дальше тренируйся в играх. Я буду рядом!": "Әнди сән компьютер ускунилирини, бехәтәр ишләш қаидилирини билисән вә қәдәмләрни тәртипкә қоялайсән. Кейин оюнларда машиқ қил. Мән йениңда болимән!",
