"После пасты на щётку нужно чистить зубы.": "Хәмир сүрүлгәндин кейин тишни чөткилиш керәк.",
"Инструкция к конструктору или игре — это ...": "Конструктор яки оюнниң көрсәтмиси ...",
"алгоритм": "алгоритм",
"картинка в рамке": "рамкидики рәсим",
"В инструкции шаги идут по порядку: это алгоритм.": "Көрсәтмидә қәдәмләр тәртип билән кәлгән: бу алгоритм.",
"Что не является алгоритмом?": "Буларниң қайсиси алгоритм әмәс?",
"Красный воздушный шарик": "Қизил һаво шари",
"Рецепт блина": "Блин рецепти",
"Инструкция к игре": "Оюн көрсәтмиси",
"Правило перехода дороги": "Йолдин өтүш қаидиси",
"Шарик — предмет, а алгоритм — порядок действий.": "Һаво шари — нәрсә, алгоритм болса һәрикәтләр тәртипи.",
"Здорово! Всё посмотрели.": "Яхши! Һәммисини көрдуқ.",
"Всё верно!": "Һәммиси тоғра!",
"Верно! Что дальше?": "Тоғра! Кейин немә?",
"Пока не сюда.": "Һазирчә бу йәргә әмәс.",
"Подумай, что идёт раньше.": "Немә илгири келидиғанлиғини ойлап көр.",
"белый": "ақ",
"Стрелка": "Оқ",
"✏️ Рисовать": "✏️ Сизиш",
"🔲 Выделить": "🔲 Талаш",
"🪣 Заливка": "🪣 Толдуруш",
