"Подумай, к какой теме относится слово. Подсказка покажет, какие слова куда идут.": "Сөзниң қайси темиға мәнсуп екәнлигини ойлап көрүң. Әскәртиш қайси сөзләрниң қәйәргә кетидиғанлиғини көрситиду.",
