"Свет и росток": "Йоруқ вә көчәт",
"Два одинаковых ростка. Один поставили на подоконник, другой убрали в тёмный шкаф. Подождём три дня.": "Икки охшаш көчәт. Бирини дәрвазә алдиға, йәнә бирини қараңғу шкафқа қойдуқ. Үч күн күтәйли.",
