"Без света росток слабеет: растениям нужен свет.": "Йоруқсиз көчәт җәввәсизлиниду: өсүмлүккә йоруқ керәк.",
"Лёд и тепло": "Муз вә иссиқлиқ",
"Два кубика льда. Один положили на тёплое блюдце на солнце, другой оставили в морозилке.": "Икки парчә муз. Бирини күндики иссиқ ликопчиға, йәнә бирини музлаткуда қалдурдуқ.",
"На солнце": "Күн астида",
"В морозилке": "Музлаткуда",
"Через несколько минут: на солнце лёд превратился в воду, в морозилке остался льдом.": "Бир нәччә минуттин кейин: күн астидики муз сувға айланди, музлаткудики муз болуп қалди.",
