"От тепла лёд тает и становится водой.": "Иссиқтин муз ерип, сувға айлиниду.",
"Тонет или плавает": "Чөкәмду яки йүзәмду",
"Опустим в воду камешек и деревянную дощечку.": "Сувға кичик тош вә кичик тахтайни салимиз.",
"Камешек": "Кичик тош",
"Дощечка": "Кичик тахтай",
"Камешек опустился на дно, а дощечка осталась на поверхности.": "Кичик тош су тегигә чөкти, тахтай болса суниң йүзидә қалди.",
"Одни предметы тонут, другие плавают": "Бәзи нәрсиләр чөкиду, бәзилири йүзиду",
"Все предметы тонут": "Барлиқ нәрсиләр чөкиду",
"Все предметы плавают": "Барлиқ нәрсиләр йүзиду",
"Предметы ведут себя в воде по-разному.": "Нәрсиләр суда һәр хил болиду.",
"Ты объяснил все опыты!": "Сән барлиқ тәҗрибиләрни чүшәндүрдүң!",
"Подумай: что изменилось и из-за чего?": "Ойлап көрүң: немә өзгәрди вә немә үчүн?",
"Дышит": "Нәпәс алиду",
"Растёт": "Өсиду",
"Нуждается в воде": "Суға еһтияҗлиқ",
"Нуждается в тепле": "Иссиқлиққа еһтияҗлиқ",
"Ходит, бегает, летает или плавает": "Маңиду, жүгүриду, учиду яки сүзиду",
