"Есть корни": "Йилтизи бар",
"Ест траву, зёрна или мясо": "От, данлар яки гөш йәйду",
"Только у животных": "Пәқәт һайванларда",
"Только у растений": "Пәқәт өсүмлүкләрдә",
"У обоих": "Иккисидиму",
"Подумай: у кошки это есть? А у ромашки?": "Ойлап көрүң: мушукта барму? Чөп гүлидичу?",
"Ты сравнил животных и растения!": "Сән һайванлар вә өсүмлүкләрни селиштурдуң!",
"Природу изучают, чтобы заботиться о ней и жить безопасно!": "Тәбиәтни униңға көйүниш вә бехәтәр яшаш үчүн үгинимиз!",
"Погода": "Һава райи",
"Безопасность": "Бехәтәрлик",
"Новое": "Йеңилиқ",
"Видео: Зачем изучать природу": "Видео: Тәбиәтни немигә үгиниш керәк",
"Зачем людям изучать растения, животных и погоду? Нажимай на картинки и узнаешь.": "Адәмләр өсүмлүк, һайван вә һава райини немигә үгиниду? Рәсимләрни бесип билиң.",
"Зачем это нужно?": "Бу немигә керәк?",
"Выбери, зачем нужно знать то, о чём спрашивает вопрос.": "Соалда сориғанни немигә билиш керәкликини таллаң.",
"Дневник погоды": "Һава райи күндилик дәптири",
"Ты будешь настоящим исследователем. Четыре дня подряд смотри в окно и на термометр и записывай в дневник погоду и температуру.": "Сән һәқиқий тәтқиқатчи болисән. Төрт күн арқилиқ дәрвазидин вә термометрға қарап, һава райи вә температурини күндилик дәптәргә йезиң.",
"Как наблюдать": "Қандақ күзитиш керәк",
"Вспомни, как правильно проводить наблюдения.": "Күзитишни қандақ тоғра елип беришни есиңизгә елиң.",
"Видео: Опыты и сравнения": "Видео: Тәҗрибә вә селиштуруш",
"Смотрим опыты": "Тәҗрибиләрни көримиз",
"Сейчас ты увидишь три опыта. Сначала посмотри, что мы приготовили. Потом нажми «Запустить опыт», увидь результат и объясни, почему так получилось.": "Әнди сән үч тәҗрибә көрисән. Авал немә тәйярлиғинимизни көрүң. Андин «Тәҗрибини башлаш» ни бесип, нәтиҗини көрүң вә немә үчүн шундақ болғанлиғини чүшәндүрүң.",
"Что получится?": "Немә болиду?",
"Подумай, что получится в опыте, и выбери ответ.": "Тәҗрибидә немә болидиғанлиғини ойлап, җавабни таллаң.",
"Животные и растения": "Һайванлар вә өсүмлүкләр",
"Давай сравним животных и растения. Выбери, у кого есть этот признак: только у животных, только у растений или у обоих.": "Һайван вә өсүмлүкләрни селиштурайли. Бу бәлгә кимдә бар екәнлигини таллаң: пәқәт һайванда, пәқәт өсүмлүктә яки иккисидә.",
"Сходства и различия": "Охшашлиқ вә пәриқ",
"Ответь на вопросы о том, чем похожи и чем отличаются животные и растения.": "Һайван вә өсүмлүкләрниң немиси охшаш, немиси пәриқлиқ екәнлиги һәққидики соалларға җавап бериң.",
"Последняя проверка: зачем изучать природу, наблюдения, опыты и сравнения.": "Ахирқи тәкшүрүш: тәбиәтни немигә үгиниш, күзитиш, тәҗрибә вә селиштуруш.",
"Теперь ты знаешь, зачем изучать природу, как проводить наблюдения, как объяснять опыты и сравнивать животных и растения. Дальше тренируйся в играх. Я буду рядом!": "Әнди сән тәбиәтни немигә үгинидиғанлиғини, қандақ күзитишни, тәҗрибиләрни қандақ чүшәндүрүшни вә һайван билән өсүмлүкни қандақ селиштурушни билисән. Кейин оюнларда машиқ қил. Мән йениңда болимән!",
