"Резкие рывки — движение не плавное.": "Тосаттин тохташ — мунтизим әмәс һәрикәт.",
"Хлопаю часто-часто, потом редко.": "Мән тез-тез қол чапимән, андин аста.",
"Часто и редко, быстро и медленно — это время.": "Тез-тез вә сирәк, тез вә аста — вақит.",
"Как правильно приземляться после прыжка?": "Секригәндин кейин қандақ тоғра қонуш керәк?",
