"Делать небрежно": "Бепәрва қилиш",
"Не делать вовсе": "Һеч қилмаслиқ",
"Усложнить можно, увеличив число повторов или скорость.": "Тәкрарлаш санини яки тезликни ашурсақ қийинлайду.",
"Что из этого — трудность при выполнении упражнений?": "Төвәндикилардин қайси бири машиқ қилғандики қийинчилиқ?",
"Скользкий пол": "Сүзүк пол",
"Удобная форма": "Қолайлиқ кийим",
"Ровная площадка": "Тәкши мәйдан",
"Скользкий пол мешает и опасен.": "Сүзүк пол тосалғу болиду вә хәтәрлик.",
"Мяч слишком тяжёлый. Что поможет?": "Топ жуда еғир. Немә ярдәм бериду?",
