"Бросать сильнее": "Техиму күчлүк ташлаш",
"Не играть никогда": "Һеч қачан ойнимаслиқ",
"Подбери инвентарь по силам.": "Күчүңгә мас җабдуқни талла.",
"Тебе трудно сделать упражнение. Что правильно?": "Бу машиқни қилиш санга қийин. Қандақ қилиш тоғра?",
"Сказать учителю и попробовать попроще": "Оқутқучиға ейтип, осанирақ қилип көрүш",
"Обидеться": "Хапа болуш",
"Бросить и уйти": "Ташлап кетиш",
"Учитель поможет: он покажет, как сделать проще.": "Оқутқучи ярдәм бериду: у қандақ осанлаштурушни көрситиду.",
"Во время упражнения стало больно. Что делать?": "Машиқ вақтида ағриди. Немә қилиш керәк?",
"Остановиться и сказать учителю": "Тохтап оқутқучиға ейтиш",
"Терпеть молча": "Ләм-мим демәй чидаш",
"Делать быстрее": "Тезирәк қилиш",
"Никому не говорить": "Һеч кимгә ейтмаслиқ",
"Если больно, нужно сразу остановиться и сказать учителю.": "Ағриса, дәрһал тохтап оқутқучиға ейтиш керәк.",
"Какой риск есть при беге в тесном зале?": "Тар залда жүгүрүшниң қандақ хәвпи бар?",
