"Станет скучно": "Зерикиш мүмкин",
"Заболят глаза": "Көз ағриши мүмкин",
"Без разминки мышцы не готовы, и можно получить травму.": "Қизитмисаң мускуллар тәйяр болмайду вә жараһәтләнгили болиду.",
"Как лучше сказать о своих умениях?": "Өз қабилийитиң һәққидә қандақ ейтиш яхши?",
