"Тренировка помогает научиться тому, что пока трудно.": "Машиқ һазирчә қийин ишни үгинишкә ярдәм бериду.",
"У тебя хорошо получается бег. Что это значит?": "Сән яхши жүгүрисән. Бу немини билдүриду?",
"Это твоя сильная сторона": "Бу сениң күчлүк тәрипиң",
