"Когда места много, можно бегать, но смотри по сторонам.": "Йәр кәң болса жүгүрсә болиду, лекин әтрапқа қаранг.",
"Как двигаться по песку?": "Қумда қандақ маңиш керәк?",
"Поднимать ноги выше, не спешить": "Путни егизрәк көтүрүп, алдирап кәтмәслик",
