"Вид еды": "Бир хил озуқ",
"Асық ату — старинная казахская народная игра.": "Асық ату — қедимки қазақ хәлқ оюни.",
"Какая игра — казахская народная?": "Қайси оюн қазақ хәлқ оюни?",
"Хоккей": "Хоккей",
"Шахматы": "Шахмат",
"Арқан тарту — перетягивание каната: народная игра.": "Арқан тарту — арқан тартиш: хәлқ оюни.",
