"Придуманная красивая чашка": "Ойлап чиқилған чирайлиқ пиала",
"Придуманная удобная одежда": "Ойлап чиқилған қолайлиқ кийим",
"Прямая": "Түз",
"Прямая линия идёт ровно, без изгибов. Так рисуют дорогу, лучи солнца, забор.": "Түз сизиқ егилмәй, тәкши кетиду. Униң билән йол, күн нури, тосма сизиду.",
"Волнистая": "Толқунсиман",
"Волнистая линия плавно изгибается. Так рисуют волны, ручей, ленту.": "Толқунсиман сизиқ мулайим егилиду. Униң билән толқун, ериқ, лента сизиду.",
"Ломаная": "Сунуқ сизиқ",
"Ломаная линия поворачивает под острыми углами. Так рисуют молнию и горы с острыми вершинами.": "Сунуқ сизиқ өткүр булуңларда бурулиду. Униң билән яшин вә учи өткүр тағларни сизиду.",
"Спираль": "Спирал",
"Спираль закручивается по кругу. Так рисуют улитку, завиток, пружинку.": "Спирал айлинип ийилиду. Униң билән илмәй, тол, пружина сизиду.",
"Толстая": "Йоғин",
"Толстая линия получается фломастером или мелком. Она яркая и смелая.": "Йоғин сизиқни фломастер яки мум қәләм билән сизиду. У йорутуқ вә җасарәтлик.",
"Тонкая": "Нәзик",
"Тонкая линия получается острым карандашом. Она лёгкая и нежная.": "Нәзик сизиқни учлуқ қурғақ қәләм билән сизиду. У йениқ вә мулайим.",
