"Мебель нужно беречь, лепи только на подложке.": "Мебельни асраш керәк, пәқәт астилиқта ясаң.",
"Из пластилина можно слепить фигурку": "Пластилиндин һәйкәлчә ясашқа болиду",
"Из пластилина лепят фигурки.": "Пластилиндин һәйкәлчиләр ясайду.",
"Так передавать безопасно.": "Шундақ бериш бехәтәр.",
"С ножницами нельзя бегать, можно пораниться.": "Қайчә билән жүгүрүшкә болмайду, жараһәтлинишкә болиду.",
"Когда работа закончена, ножницы кладут на место": "Иш тамамлангандин кейин қайчини орниға қоюш керәк",
"Инструменты после работы убирают.": "Иш тамамлангандин кейин қураллар жиғиштурулиду.",
"Клей нельзя пробовать, он несъедобный.": "Елимниң тәмини тетишқа болмайду, у йеғили болмайду.",
"Кисточку после работы нужно вымыть": "Иш тамамлангандин кейин мо қәләмни жуюш керәк",
"Кисть моют в воде, чтобы она не засохла.": "Мо қәләмни қуруп қатмисун дәп сувда жуйду.",
"На выставке работы смотрят глазами и не трогают руками": "Көргәзмидә әсәрләргә көз билән қарайду, қол билән тутмайду",
"Работы можно испортить, поэтому трогать их нельзя.": "Әсәрләрни бузуп қоюшқа болиду, шуңа тутушқа болмайду.",
"Можно смеяться над чужим рисунком": "Башқиларниң рәсимигә күлүшкә болиду",
"Над чужой работой смеяться нельзя, это обидно.": "Башқиларниң әсиригә күлүшкә болмайду, бу көңүл ағритиду.",
"Другу можно сказать доброе слово о его рисунке": "Достниң рәсими һәққидә яхши сөз ейтишқа болиду",
"Доброе слово радует автора.": "Яхши сөз автурни хошал қилиду.",
"Свою работу можно подписать названием": "Өз әсириңгә нам қоюшқа болиду",
"У каждой работы есть название.": "Һәр бир әсәрниң нами бар.",
"Можно рассказать, чем ты рисовал и что хотел показать": "Немә билән сизғиниңни вә немини көрсәтмәкчи болғиниңни ейтишқа болиду",
"Рассказ помогает зрителям понять работу.": "Сөзләп бериш көрүрмәнләргә әсәрни чүшинишкә ярдәм бериду.",
"дают": "чиқириду",
"Основные цвета: красный, жёлтый и синий. Остальные получаются, когда их смешивают.": "Асасий рәңләр: қизил, сери вә көк. Қалған рәңләр уларни арилаштурғанда чиқиду.",
"Правильный цвет:": "Тоғра рәң:",
