"Холодный": "Совуқ",
"Тёплые цвета как солнце и огонь: красный, оранжевый, жёлтый. Холодные как лёд и вода: синий, голубой, фиолетовый.": "Иссиқ рәңләр Күн вә отқа охшаш: қизил, тоқ сериқ, сери. Совуқ рәңләр муз вә сувға охшаш: көк, һава рәң, бәнәпшә.",
"Тёплыми": "Иссиқ рәңләр",
"Холодными": "Совуқ рәңләр",
"Тёплые цвета рассказывают о радости и жаре, холодные о тишине и холоде.": "Иссиқ рәңләр хошаллиқ вә иссиқни, совуқ рәңләр тиниқлиқ вә совуқни әкс әттүриду.",
