"Видео: Искусство и чувства": "Видео: Сәнъәт вә һессиятлар",
"Искусство нашей страны": "Дөлитимизниң сәнъити",
"Ковры": "Гиләмләр",
"Войлочные ковры": "Кигиз гиләмләр",
"Казахские мастерицы делают из войлока красивые ковры с узорами: кошму и сырмак. Тұскиіз — расшитый ковёр на стену юрты.": "Қазақ уста аяллири кигиздин нәқишлик чирайлиқ гиләмләр ясайду: кигиз вә сырмақ. Тускиз — киз өйниң девалиға есилидиған көрмә гиләм.",
"Юрта — это дом кочевников. Она круглая, лёгкая и красиво украшена узорами.": "Киз өй — көчмәнләрниң өйи. У юмилақ, йениқ вә нәқишләр билән чирайлиқ безәлгән.",
"Домбра и кюй": "Домбра вә күй",
"Домбра — казахский музыкальный инструмент. Кюй — музыка, в которой композитор рассказывает о природе и чувствах.": "Домбра — қазақ музика ускунисини. Күй — бастикар табиәт вә һессиятлар һәққидә сөзләйдиған музика.",
"Мир": "Дунья",
"Искусство мира": "Дунья сәнъити",
"У каждого народа свои картины, скульптуры, здания и узоры. Все они рассказывают о людях и их чувствах.": "Һәр хәлқниң өз картиналири, һәйкәллири, иморәтлири вә нәқишлири бар. Булар һәммиси адәмләр вә уларниң һессиятлири һәққидә сөзләйду.",
"Искусство рассказывает о чувствах. В Казахстане его создают веками: войлочные ковры, юрты, музыка домбры. И у других народов мира тоже много красивых произведений. Нажимай на картинки и знакомься.": "Сәнъәт һессиятлар һәққидә сөзләйду. Қазақстанда уни әсирләр бойи яритип кәлгән: кигиз гиләмләр, киз өйләр, домбра музикиси. Дуньадики башқа хәлқләрдиму нурғун чирайлиқ әсәрләр бар. Рәсимләрни бесип тонушуң.",
"Что мы знаем об искусстве": "Сәнъәт һәққидә немини билимиз",
"Ответь на вопросы про искусство нашей страны и про то, что такое произведение искусства.": "Дөлитимиз сәнъити вә сәнъәт әсири дегән немә екәнлиги һәққидики соалларға җавап бериң.",
"Какое настроение?": "Қандақ кәйпият?",
"Посмотри на картинку и скажи, какое настроение она передаёт. Помогут цвета: тёплые и яркие радуют, тёмные и холодные грустят или тревожат.": "Рәсимгә қарап, у қандақ кәйпиятни билдүридиғанлиғини ейтиң. Рәңләр ярдәм бериду: иссиқ вә йорутуқ рәңләр хошаллиқ, қараңғу вә совуқ рәңләр қайғу яки тәшвиш пәйда қилиду.",
"Видео: Графика: приёмы": "Видео: Графика усуллири",
"Приёмы графики": "Графика усуллири",
"В графике много приёмов: линия, штриховка и точки. Вспомни, для чего они нужны.": "Графикида көп усул бар: сизиқ, штрих вә нуқта. Уларниң немигә керәклигини есиңизгә елиң.",
"Рисуем разными приёмами": "Һәр хил усуллар билән сизимиз",
"Нарисуй линию карандашом": "Қурғақ қәләм билән бир сизиқ сизиң",
"Выбери «Карандаш» и проведи пальцем или мышкой по листу.": "«Қурғақ қәләм» ни таллап, бармақ яки чичқанчә билән варақ үстидә сизиң.",
"Нарисуй фигуру фломастером и заштрихуй её": "Фломастер билән бир шәкил сизип, штрих салың",
"Сначала «Фломастер», потом «Штриховка».": "Авал «Фломастер» ни, андин «Штрих» ни таллаң.",
"Сделай точками небо или землю": "Нуқтилар билән асман яки йәр сизиң",
"Выбери «Точки» и веди по листу.": "«Нуқта» ни таллап, варақ үстидә жилдуруң.",
"Нарисуй дерево, дом или животное тремя разными приёмами": "Үч хил усул билән дәрәқ, өй яки һайван сизиң",
"Попробуй разные инструменты и цвета: художники всегда экспериментируют.": "Һәр хил қурал вә рәңләрни синап көрүң: рәссамлар һемишә тәҗрибә қилиду.",
"Теперь порисуем разными приёмами. Выполняй задания по порядку. Пробуй карандаш, фломастер, штриховку и точки. Ты можешь стереть всё и начать заново.": "Әнди һәр хил усуллар билән сизайли. Тапшуруқларни тәртип билән орундаң. Қурғақ қәләм, фломастер, штрих вә нуқтиларни синап көрүң. Һәммини өчүрүп қайтидин башлашқа болиду.",
"Моя работа": "Мениң ишим",
"Расскажи о своём рисунке.": "Рәсиминг һәққидә ейтиң.",
"Что я нарисовал": "Мән немә сиздим",
"Животное": "Һайван",
"Узор": "Нәқиш",
