"просто «девочка»": "пәқәт «қиз бала»",
"Это обычное слово, поэтому пишем с маленькой буквы.": "Бу әдәттики сөз, шуңа кичик һәрип билән йезиду.",
"пишут с большой буквы.": "чоң һәрип билән йезилиду.",
