"Все предложения собраны!": "Барлиқ җүмлиләр йиғилди!",
"Не то слово. Кто это делает? Что он делает? Глагол — в конце.": "Бу сөз әмәс. Буни ким қилиду? У немә қилиду? Пеил ахирида.",
"Ты пересказал истории по картинкам!": "Сән рәсимләр бойичә һекайиләрни қайта ейттиң!",
"Верно! Следующая история.": "Тоғра! Кейинки һекайә.",
"Ты узнал много новых казахских слов!": "Сән нурғун йеңи қазақ сөзлирини үгәндиң!",
"Ты знаешь цвета и числа по-казахски!": "Сән қазақчә рәң вә санларни билисән!",
"Предмет отвечает на вопросы КІМ? НЕ? (кто? что?).": "Нәрсә КІМ? НЕ? (ким? немә?) соаллириға җавап бериду.",
