"К каждой футболке подбери по очереди каждую шапку:": "Һәр бир футболкиға һәр бир қалпақни кезәк билән таллаң:",
"нужно выбрать два. Сколько разных пар получится? (Пары": "икки таллаш керәк. Нәччә хил жүп чиқиду? (Жүпләр",
