"ниже": "пакарирақ",
"Выше — значит, на этаж ближе к крыше": "Егизирәк — шипқа бир қәвәт йеқинирақ",
"Ниже — значит, на этаж ближе к земле": "Пакарирақ — йәргә бир қәвәт йеқинирақ",
