"Мячик лежит ... со столом.": "Топ үстәл билән ... .",
"внутри": "ичидә",
"снаружи": "сиртида",
"Мячик внутри коробки: коробка окружает его со всех сторон.": "Топ қутиниң ичидә: қути уни һәр тәрәптин қоршап туриду.",
"Мячик вне коробки, то есть снаружи.": "Топ қутиниң сиртида, йәни ташқири тәрәптә.",
"Кружки стоят слева направо:": "Дөңгиликләр солдин оңға тизилған:",
"шире": "кәңрәк",
"уже": "тарирақ",
"толще": "қелинрақ",
"тоньше": "юпқа",
"Сравни два предмета.": "Икки нәрсини селиштуруң.",
"тот, который": "болғини",
"высоте": "егизлик",
"ширине": "кәңлик",
"толщине": "қелинлиқ",
