"Условие": "Шәрт",
"Это вопрос: в нём спрашивают, что нужно найти, и он заканчивается знаком «?».": "Бу — соал: униңда немә издәш керәклиги соралиду вә у «?» билән ахирлишиду.",
"Это условие: в нём сказано, что известно. Искать здесь ничего не нужно.": "Бу — шәрт: униңда мәлум нәрсә ейтилған. Бу йәрдә һеч нәрсә издәш керәк әмәс.",
