"Нажми на каждый элемент множества по одному разу. Так ты посчитаешь, сколько их.": "Топламниң һәр элементини бир қетимдин бесиң. Шундақ қилсиңиз нәччә екәнлигини санайсиз.",
"элемент": "элемент",
"В множестве": "Топламда",
"элемента": "элемент",
"элементов": "элемент",
"Объединение: A и B вместе": "Бирләштүрүш: A вә B биллә",
"Есть два множества: в A —": "Икки топлам бар: A да —",
". Нажми «Объединить» и посмотри, сколько станет элементов.": ". «Бирләштүрүш» ни бесип, элемент қанчә болидиғанлиғини көрүң.",
"Когда множества объединяют, их элементы собирают вместе:": "Топламларни бирләштүргәндә уларниң элементлири бир йәргә жиғилиду:",
"Видео: Что такое множество": "Видео: Топлам дегән немә",
"Собираем множества": "Топламларни түзимиз",
"Привет! Это Барсик. Когда предметы собраны в одну группу по общему признаку, это множество. Например, все фрукты — одно множество, все игрушки — другое. Раскладывай предметы по множествам.": "Салам! Мән Барсик. Нәрсиләр ортақ бәлгү бойичә бир топқа жиғилса, бу топлам болиду. Мәсилән, барлиқ мевиләр — бир топлам, барлиқ ойунчуқлар — башқа топлам. Нәрсиләрни топламларға айриң.",
"Что не входит в множество?": "Немә бу топламға кирмәйду?",
"В множество входят предметы с общим признаком. Найди предмет, который не подходит к этой группе.": "Топламға ортақ бәлгүлүк нәрсиләр кириду. Бу топқа мас кәлмәйдиған нәрсини тепиң.",
"Входит или не входит?": "Киридуму яки кирмәмду?",
"Предметы, из которых состоит множество, называют его элементами. Посмотри на множество и ответь, есть ли в нём нужный элемент.": "Топламни түзидиған нәрсиләр униң элементлири дәп атилиду. Топламға қарап, униңда керәклик элемент бар-йоқлуғиға җавап бериң.",
"Видео: Элементы множества": "Видео: Топламниң элементлири",
"Считаем элементы": "Элементларни санаймиз",
"У каждого множества есть элементы, и их можно посчитать. Нажимай на элементы по одному, и они получат номера.": "Һәр топламниң элементлири бар, уларни санашқа болиду. Элементларни бир-бирләп бесиң, улар номур алиду.",
"Сколько элементов?": "Нәччә элемент?",
"Посчитай, сколько предметов в множестве. Это и есть число его элементов.": "Топламда нәччә нәрсә барлиғини санаң. Бу — униң элемент сани.",
"Пустое множество": "Бош топлам",
"Бывает и так, что подходящих предметов нет совсем. Множество без элементов называют пустым. В нём ноль элементов.": "Баъзида мас келидиған нәрсә бутунләй болмайду. Элементсиз топлам бош топлам дәп атилиду. Униңда нөл элемент бар.",
"Видео: Объединяем множества": "Видео: Топламларни бирләштүримиз",
"Собираем вместе": "Биллә жиғимиз",
"Два множества можно объединить в одно: тогда все их элементы окажутся вместе. Нажми «Объединить» и посмотри, сколько получится.": "Икки топламни бир топламға бирләштүрүшкә болиду: шуниң билән уларниң барлиқ элементлири бир йәргә жиғилиду. «Бирләштүрүш» ни бесип, қанчә болидиғанлиғини көрүң.",
"Сколько в объединении?": "Бирләштүрүлгәндә қанчә?",
"Чтобы узнать, сколько элементов стало в объединении, сложи числа элементов обоих множеств.": "Бирләштүргәндин кейин қанчә элемент болғанлиғини билиш үчүн икки топламниң элемент санини қошуң.",
"Где больше?": "Қайси тәрәптә көп?",
"Множества можно сравнивать по числу элементов. Посчитай элементы в каждом и выбери, где больше или меньше.": "Топламларни элемент сани бойичә селиштурушқа болиду. Һәр топламдики элементларни санап, қайсисида көп яки аз екәнлигини таллаң.",
"Последняя проверка курса: множества, элементы, пустое множество и объединение.": "Курсниң ахирқи тәкшүрүши: топламлар, элементлар, бош топлам вә бирләштүрүш.",
"Теперь ты знаешь, что такое множество и его элементы, умеешь находить пустое множество, объединять множества и сравнивать их. Дальше — тренировка без конца в игре. Я буду рядом!": "Һазир сән топлам вә униң элементлириниң немә екәнлигини билисән, бош топламни тепип, топламларни бирләштүрүп вә селиштуралайсән. Кейин оюнда ахирсиз машиқ қилиң. Мән йениңда болимән!",
