"Каждая палочка — один десяток. Сколько здесь десятков?": "Һәр таяқ бир онлуқ. Бу йәрдә нәччә онлуқ бар?",
"Посчитай палочки по одной: их": "Таяқларни бирдин санаң: җәми",
