"В каждой палочке 10 кубиков. Сколько всего кубиков?": "Һәр таяқта 10 кубик бар. Җәми нәччә кубик бар?",
"Считаем десятками:": "Онлап санаймиз:",
"Какое число пропущено?": "Қайси сан чүшүп қалди?",
"Числа идут": "Бу санлар онлап",
"по десять:": "тәртип билән туриду:",
". Пропущено": ". Чүшүп қалғини —",
"Считаем десятками. Какое число идёт": "Онлап санаймиз. Андин қайси сан келиду?",
"десяткам добавляем ещё один десяток:": "Онлуқларға йәнә бир онлуқ қошимиз:",
"Берём на один десяток меньше: перед": "Бир онлуқ кам алимиз:",
