"Сравни десятки:": "Онлуқларни селиштуруң:",
"Десятков больше у": "Онлуқ көп болғини —",
"Десятков": "Онлуқ",
"Один десяток — 10, два десятка — 20, три десятка — 30. Считаем десятками!": "Бир онлуқ — 10, икки онлуқ — 20, үч онлуқ — 30. Онлап санаймиз!",
", это": ", бу",
"Дальше идёт": "Андин кейин",
"Это десять десятков. Перед ним стоит": "Бу он онлуқ. Униң алдидики —",
"Перед ним": "Униң алдида",
", после него": ", униң кейинидә",
"Считаем десятками: 10, 20, 30, ... до ста.": "Онлап санаймиз: 10, 20, 30… йүзгичә.",
"Разобрано примеров:": "Үгинилгән мисаллар:",
"дес. =": "онлуқ =",
"Десятки складывают и вычитают так же, как обычные числа.": "Онлуқларни қошуш вә айриш — адәттики санларниңкидәк.",
"Видео: Палочки-десятки": "Видео: Онлуқ таяқчилири",
"Один десяток — это 10": "Бир онлуқ — 10",
"Привет! Это Барсик. Десять кубиков можно собрать в одну палочку, и это один десяток. Меняй число палочек кнопками и смотри, сколько получается кубиков.": "Салам! Мән Барсик. Он кубикни бир таяқчә қилип жиғишқа болиду, бу бир онлуқ. Төгмиләр билән таяқ санини өзгәртип, қанчә кубик болидиғанлиғини көрүң.",
"Сколько десятков?": "Нәччә онлуқ?",
"Каждая палочка — это один десяток. Посчитай палочки и выбери ответ.": "Һәр таяқ бир онлуқ. Таяқларни санап, җавапни таллаң.",
"Сколько всего кубиков?": "Җәми нәччә кубик бар?",
"В каждой палочке десять кубиков. Считай десятками: десять, двадцать, тридцать, и так далее.": "Һәр таяқта он кубик бар. Онлап санаң: он, жигирмә, оттуз вә башқилар.",
"Видео: Считаем десятками": "Видео: Онлап санаймиз",
"Десять, двадцать, тридцать": "Он, жигирмә, оттуз",
"Нажимай на круглые числа от десяти до ста. Я покажу, сколько в каждом десятков и какое число стоит рядом.": "Ондин йүзгичә онлуқ санларни бесиң. Мән һәр бириниң нәччә онлуқ барлиғини вә йенида қайси сан туридиғанлиғини ейтип беримән.",
"Считай десятками вперёд и назад и найди пропущенное число.": "Онлап алдиға вә кейингә санап, чүшүп қалған санни тепиң.",
"Как называются круглые числа": "Онлуқ санлар қандақ атилиду",
"У каждого круглого числа своё имя: двадцать, тридцать, сорок. Запомни, как оно называется и как записывается.": "Һәр бир онлуқ санниң өз нами бар: жигирмә, оттуз, қириқ. Униң немә дәп атилидиғанлиғини вә қандақ йезилидиғанлиғини есиңизда тутуң.",
"Расставь круглые числа от меньшего к большему. Нажимай на числа по очереди: сначала самое маленькое.": "Онлуқ санларни кичиктин чоңға тизиң. Санларни кетма-кет бесиң: алди билән әң кичигини.",
"Видео: Складываем и вычитаем десятки": "Видео: Онлуқ санларни қошуш вә айриш",
"Десятки плюс десятки": "Онлуқ плюс онлуқ",
"Три десятка и два десятка — это пять десятков. А пять десятков — это пятьдесят. Выбирай сложение или вычитание и смотри примеры.": "Үч онлуқ вә икки онлуқ — бәш онлуқ. Бәш онлуқ — әллик. Қошушни яки айришни таллап, мисалларни көрүң.",
"Складываем десятки": "Онлуқ санларни қошимиз",
"Считай десятками: сколько десятков получилось, столько и десятков в ответе.": "Онлап санаймиз: нәччә онлуқ чиқса, җавапта шунчә онлуқ болиду.",
"Вычитаем десятки": "Онлуқ санларни айримиз",
"Из одних десятков вычти другие. Посчитай, сколько десятков осталось.": "Бирнәччә онлуқтин башқа онлуқларни айриң. Нәччә онлуқ қалғанлиғини санаң.",
"Видео: Сравниваем и повторяем": "Видео: Селиштуруш вә тәкрарлаш",
"Сравни десятки: где десятков больше, то число больше. Открытая сторона знака смотрит на большее число.": "Онлуқларни селиштуруң: онлуқ көп болған сан чоң. Бәлгүниң ечилған тәрипи чоң санға қарайду.",
"Последняя проверка курса: счёт десятками, названия чисел, сложение, вычитание и сравнение десятков.": "Курсниң ахирқи тәкшүрүши: онлап санаш, санларниң намлири, онлуқ санларни қошуш, айриш вә селиштуруш.",
"Теперь ты умеешь считать десятками до ста, называть и записывать круглые числа, складывать и вычитать десятки и сравнивать их. Дальше — тренировка без конца в игре. Я буду рядом!": "Һазир сән онлап йүзгичә санайалайсән, онлуқ санларни атап йезиәләйсән, онлуқ санларни қошуп айриялайсән вә селиштуралайсән. Кейин оюнда ахирсиз машиқ қилиң. Мән йениңда болимән!",
"часа": "саәт",
"часов": "саәт",
"Утром Барсик просыпается, умывается и завтракает.": "Әтигәндә Барсик ойғинип, жүзини жуйиду вә әтигәнлик чай ичиду.",
"Днём солнце высоко. Барсик учится, играет и обедает.": "Күндүзи қуяш егиз туриду. Барсик оқуйду, ойнайду вә чүшлүк тамақ йәйду.",
"Вечером солнце садится. Барсик ужинает и гуляет.": "Кечидә қуяш петиду. Барсик кәчлик тамақ йәйду вә сайәһәткә чиқиду.",
"Ночью темно, видны луна и звёзды. Барсик спит.": "Кечә қарангғу, ай вә йултузлар көрүниду. Барсик ухлаватиду.",
