"Чёткий взмах — вступление: все начинают вместе.": "Ениқ силкиш — башлаш ишариси: һәммә биллә башлайду.",
"Дирижёр сжал руки в кулак. Что делаем?": "Дирижёр қолини муштум қилди. Биз немә қилимиз?",
"Заканчиваем пение": "Нахшини тамамлаймиз",
"Начинаем петь": "Ейтишни башлаймиз",
"Поём громче": "Қаттиқрақ ейтимиз",
"Поём быстрее": "Тезирәк ейтимиз",
"Кулак означает конец: заканчиваем петь.": "Муштум — ахир: нахшини тохтитимиз.",
"Руки дирижёра стали шире, взмахи большие. Как петь?": "Дирижёрниң қоллири кәңрәк ечилди, силкишлири чоң. Қандақ ейтимиз?",
