"Дирижёр": "Дирижёр",
"Композитор": "Композитор",
"Слушатель": "Аңлиғучи",
"Хором или оркестром управляет дирижёр.": "Хор яки оркестрни дирижёр башқуриду.",
"Как называется часть песни, которая повторяется с одинаковыми словами?": "Нахшиниң охшаш сөзләр билән тәкрарлинидиған қисми немә дәп атилиду?",
"Припев": "Нақарат",
"Куплет": "Куплет",
"Пауза": "Пауза",
"Припев повторяется после каждого куплета.": "Нақарат һәр куплеттин кейин тәкрарлиниду.",
"Как называется часть песни, в которой слова каждый раз новые?": "Нахшиниң һәр қетим сөзлири йеңи болидиған қисми немә дәп атилиду?",
"В каждом куплете слова новые.": "Һәр куплетниң сөзлири йеңи.",
"Песня: куплет, припев, куплет, припев. Сколько раз пели припев?": "Нахша: куплет, нақарат, куплет, нақарат. Нақарат нәччә қетим ейтилди?",
"Припев пели после первого куплета и после второго: два раза.": "Нақарат биринчи куплеттин кейин вә иккинчисидин кейин ейтилди: икки қетим.",
"Какая часть песни повторяется и легко запоминается?": "Нахшиниң қайси қисми тәкрарлинип, ядқа елиш асан?",
"Припев повторяется, поэтому его легко запомнить.": "Нақарат тәкрарлинидиған болғачқа, уни ядқа елиш асан.",
"Из куплетов и припева": "Куплет вә нақаратлардин",
"Из одних нот": "Пәқәт ноталардин",
"Из одних пауз": "Пәқәт паузилардин",
"Песню составляют куплеты и припев.": "Нахша куплет вә нақаратлардин түзүлиду.",
"Песня начинается обычно с ...": "Нахша адәттә ... дин башлиниду",
"куплета": "куплет",
"паузы": "паузидин",
"аплодисментов": "алқиш садасидин",
"Чаще всего песня начинается с куплета, а потом звучит припев.": "Нахша көпинчә куплеттин башлиниду, андин нақарат аңлиниду.",
"Послушай музыку. Какой это жанр?": "Музикини аңлаң. Бу қандақ жанр?",
"Чёткий, ровный шаг: это марш. Под него шагают.": "Ениқ, тәкши қәдәм: бу марш. Униңға қәдәм ташлайду.",
"Лёгкая кружащаяся музыка: это танец (вальс). Под неё танцуют.": "Йеник айлинидиған музика: бу — уссул (вальс). Униңға уссул ойнайду.",
"Плавная напевная мелодия: это песня (колыбельная). Её можно петь.": "Ястуқ, нахшиға охшаш мақам: бу — нахша (бешик нахшиси). Уни ейтишқа болиду.",
