"В такт! Попали:": "Бәлгүгә дәл тегиштиң! Тегишти:",
". Следующий раунд.": ". Кейинки раунд.",
"Попал в такт:": "Бәлгүгә тегиштиң:",
", лишних ударов:": ", артуқ уруш:",
". Нужно": ". Керәк",
". Попробуй ещё раз!": ". Йәнә бир қетим синап көрүң!",
"Нажимай на клетки: в каждом столбце выбери одну ноту.": "Көзәкләрни бесиң: һәр бир мунарда бирдин нота таллаң.",
"Мелодия готова! Ты композитор.": "Мақам тәйяр! Сән композитор.",
"Нот в мелодии:": "Мақамдики нота сани:",
"из 8. Нужно не меньше 6 и нажать «Сыграть».": ", җәми 8. Кеминдә 6 керәк, андин «Челиш» ни бесиң.",
