"Нужное или только хочется? Пятая игрушка-машинка.": "Керәкму яки пәқәт халаймизму? Бәшинчи ойунчуқ машина.",
"Игрушки приятны, но жить без них можно.": "Ойунчуқлар хошал қилиду, лекин уларсиму яшашқа болиду.",
"Нужное или только хочется? Мороженое каждый день.": "Керәкму яки пәқәт халаймизму? Һәр күни мозай.",
"Сладкое можно иногда. Без него можно жить.": "Тәтлик нәрсини вақит-вақитта йейишкә болиду. Усиз яшашқа болиду.",
"Нужное или только хочется? Лекарство, когда болеешь.": "Керәкму яки пәқәт халаймизму? Ағриғанда дора.",
"Когда человек болеет, лекарство нужно, но его даёт врач или взрослые.": "Адәм ағриғанда дора керәк, лекин уни дохтур яки чоңлар бериду.",
"Нужное или только хочется? Школьные тетради.": "Керәкму яки пәқәт халаймизму? Мәктәп дәптәрлири.",
"Тетради нужны для учёбы.": "Дәптәр оқуш үчүн керәк.",
"Откуда берётся молоко?": "Сүт қәйәрдин кәлгән?",
"От коровы на ферме": "Фермидики кала",
"С фабрики игрушек": "Ойунчуқ фабрикисидин",
"Из моря": "Деңиздин",
"Из облака": "Булуттин",
"Молоко дают коровы, козы и овцы.": "Сүтни кала, ечкә вә қой бериду.",
"Откуда берётся яблоко?": "Алма қәйәрдин кәлгән?",
"Из сада, с дерева": "Бағдики дәрәхтин",
"Из шахты": "Кан орнидин",
"Из лаборатории": "Лабораториядин",
"Из океана": "Окяндин",
"Яблоки растут на яблонях в саду.": "Алма бағдики алма дәрихида өсиду.",
"Откуда берётся хлеб?": "Нан қәйәрдин кәлгән?",
"Из пекарни": "Нанвайханидин",
"Из леса": "Ормандин",
"Из больницы": "Дохтурханидин",
"Хлеб пекут из муки в пекарне.": "Нанни нанвайханида ундин йопиду.",
"Откуда берётся мука для хлеба?": "Нан йоқниң уни қәйәрдин кәлгән?",
"Из зерна пшеницы": "Буғдай данлиридин",
"Из камней": "Ташлардин",
"Из молока": "Сүттин",
"Из песка": "Қумдин",
"Муку мелют из зерна, а зерно растёт в поле.": "Унни дәндин тарттиду, дән етизлиқта өсиду.",
