"Из шерсти овцы": "Қой жүнидин",
"Из воды": "Судин",
"Из железа": "Темирдин",
"Шерсть овец прядут в нить и вяжут из неё тёплые вещи.": "Қой жүнини жип қилип йигирип, униңдин иссиқ кийим тоқуйду.",
"Где растут огурцы и помидоры?": "Қалмақ вә помидор қәйәрдә өсиду?",
